fn report(model: &LinearTriadModel, reason: TerminationReason) -> ospf_rust_core::Result<SolveReport<f64>> {
    let mut builder = SolveReport::builder(if reason == TerminationReason::Completed { ProblemStatus::Feasible } else { ProblemStatus::Unknown }, reason)
        .fingerprints(SolveFingerprints { model: Some(linear_model_fingerprint(model)?), ..Default::default() }).model_mapping(Some(linear_model_mapping(model)?));
    if reason == TerminationReason::Completed {
        let mut solution = SolveSolution::vector(vec![3.0]); solution.objective_value = Some(3.0 * model.c[0]);
        if !model.has_integer_variables() { solution.dual_solution = Some(vec![-2.0, 0.0]); }
        builder = builder.solution(solution).proof(SolveProof::optimality());
    }
    builder.build()
}

