#[test]
fn terminal_lp_reports_preserve_actual_stops_and_never_open_an_unjustified_final() {
    let request = request(); let handle = SolveHandle::new();
    for reason in [TerminationReason::Completed, TerminationReason::TimeLimit, TerminationReason::Cancelled, TerminationReason::Interrupted, TerminationReason::BackendFailure] {
        let text = execute(&request.model, request.csp2d_options.clone().unwrap(), Arc::new(Fake(move |model: &LinearTriadModel, _: &SolveOptions<'_>| report(model, reason))),
            &SolveOptions { cancellation_handle: Some(&handle), ..Default::default() }).unwrap();
        let decoded = decode_csp2d_execution_report(&text, &request.model).unwrap();
        assert_eq!(decoded.production.is_some(), reason == TerminationReason::Completed);
        assert_eq!(decoded.summary.stage_count, if reason == TerminationReason::Completed { 2 } else { 1 });
        assert_eq!(decoded.summary.stop, match reason { TerminationReason::Completed => Csp2dExecutionStop::IterationLimit, TerminationReason::TimeLimit => Csp2dExecutionStop::TimeLimit,
            TerminationReason::Cancelled => Csp2dExecutionStop::Cancelled, _ => Csp2dExecutionStop::MasterStopped });
    }
}

#[test]
fn precancellation_expired_budget_and_backend_failure_never_generate_substitute_production() {
    let request = request();
    for cancel in [false, true] {
        let handle = SolveHandle::new(); if cancel { handle.cancel(CancellationOrigin::External); }
        let solver = Arc::new(Fake(|_: &LinearTriadModel, _: &SolveOptions<'_>| -> ospf_rust_core::Result<SolveReport<f64>> { panic!("stopped execution must not call the solver") }));
        let text = execute(&request.model, request.csp2d_options.clone().unwrap(), solver,
            &SolveOptions { cancellation_handle: Some(&handle), time_limit: Some(if cancel { Duration::from_secs(60) } else { Duration::ZERO }), ..Default::default() }).unwrap();
        let result = decode_csp2d_execution_report(&text, &request.model).unwrap(); assert!(result.production.is_none()); assert_eq!(result.summary.stage_count, 0);
        assert_eq!(result.summary.stop, if cancel { Csp2dExecutionStop::Cancelled } else { Csp2dExecutionStop::TimeLimit });
    }
    let handle = SolveHandle::new();
    assert!(execute(&request.model, request.csp2d_options.unwrap(), Arc::new(Fake(|_: &LinearTriadModel, _: &SolveOptions<'_>| {
        Err(ospf_rust_core::SolverError::NotAvailable("test runtime unavailable".into()).into())
    })), &SolveOptions { cancellation_handle: Some(&handle), ..Default::default() }).is_err());
}

#[test]
fn failed_workers_retain_diagnostics_without_substitute_reports_or_leaked_capacity() {
    let engine = NativeEngine::new(1);
    for panic in [false, true] {
        let request = request(); let source = request.model.clone(); let configuration = request.csp2d_options.clone().unwrap();
        let solver = Arc::new(Fake(move |_: &LinearTriadModel, _: &SolveOptions<'_>| -> ospf_rust_core::Result<SolveReport<f64>> {
            if panic { panic!("CSP2D test backend panic"); }
            Err(ospf_rust_core::SolverError::NotAvailable("CSP2D test runtime unavailable".into()).into())
        }));
        let submitted = engine.start_encoded(request, move |options| execute(&source, configuration, solver, options)).unwrap();
        let deadline = Instant::now() + Duration::from_secs(5);
        let view = loop { let view = engine.get(&submitted.id).unwrap(); if view.status != JobStatus::Running { break view; }
            assert!(Instant::now() < deadline); std::thread::yield_now(); };
        assert_eq!(view.status, JobStatus::Failed); assert!(view.report_json.is_none());
        let error = view.error.unwrap();
        if panic { assert_eq!(error.code, "SolverPanic"); }
        else { assert!(error.message.contains("CSP2D test runtime unavailable")); }
        let retained = engine.cancel(&submitted.id).unwrap(); assert_eq!(retained.status, JobStatus::Failed); assert!(retained.report_json.is_none());
        engine.release(&submitted.id).unwrap(); assert_eq!(engine.get(&submitted.id).unwrap_err().code, "NotFound");
    }
}

#[test]
fn cancellation_waits_for_the_actual_child_and_completed_results_win_late_cancel() {
    let request = request(); let source = request.model.clone(); let engine = NativeEngine::new(1);
    let (entered_tx, entered_rx) = sync_channel(1); let (finish_tx, finish_rx) = sync_channel(1); let finish_rx = Mutex::new(finish_rx);
    let solver = Arc::new(Fake(move |model: &LinearTriadModel, options: &SolveOptions<'_>| {
        entered_tx.send(()).unwrap(); finish_rx.lock().unwrap().recv().unwrap();
        assert!(options.cancellation_handle.unwrap().is_cancelled()); report(model, TerminationReason::Cancelled)
    }));
    let configuration = request.csp2d_options.clone().unwrap(); let copy = source.clone();
    let submitted = engine.start_encoded(request, move |options| execute(&copy, configuration, solver, options)).unwrap();
    entered_rx.recv_timeout(Duration::from_secs(5)).unwrap();
    assert_eq!(engine.cancel(&submitted.id).unwrap().status, JobStatus::Running);
    assert_eq!(engine.release(&submitted.id).unwrap_err().code, "Busy"); finish_tx.send(()).unwrap();
    let deadline = Instant::now() + Duration::from_secs(5);
    let view = loop { let view = engine.get(&submitted.id).unwrap(); if view.status != JobStatus::Running { break view; }
        assert!(Instant::now() < deadline); std::thread::yield_now(); };
    assert_eq!(view.status, JobStatus::Completed, "{:?}", view.error);
    let text = view.report_json.unwrap(); assert_eq!(decode_csp2d_execution_report(&text, &source).unwrap().summary.stop, Csp2dExecutionStop::Cancelled);
    assert_eq!(engine.cancel(&submitted.id).unwrap().report_json.as_ref(), Some(&text)); engine.release(&submitted.id).unwrap();
    assert_eq!(engine.get(&submitted.id).unwrap_err().code, "NotFound");
}

#[test]
fn completed_final_incumbent_is_not_rewritten_when_parent_cancellation_arrives_late() {
    let request = request(); let parent = SolveHandle::new(); let captured = parent.clone();
    let solver = Arc::new(Fake(move |model: &LinearTriadModel, _: &SolveOptions<'_>| {
        if model.has_integer_variables() { captured.cancel(CancellationOrigin::External); }
        report(model, TerminationReason::Completed)
    }));
    let text = execute(&request.model, request.csp2d_options.unwrap(), solver, &SolveOptions { cancellation_handle: Some(&parent), ..Default::default() }).unwrap();
    let decoded = decode_csp2d_execution_report(&text, &request.model).unwrap();
    assert!(parent.is_cancelled()); assert_eq!(decoded.summary.stop, Csp2dExecutionStop::IterationLimit);
    assert_eq!(decoded.summary.integer.unwrap().termination_reason, "COMPLETED"); assert_eq!(decoded.production.unwrap().produced_counts["a"], "3");
}
